<template><div class="page"><el-card><template #header><span>用户收藏</span></template><el-table :data="list" border><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="user_id" label="用户ID" width="100"/><el-table-column prop="nickname" label="用户"/><el-table-column label="商品" min-width="200"><template #default="{row}"><div style="display:flex;align-items:center;gap:10px"><el-image v-if="row.main_image" :src="row.main_image" style="width:50px;height:50px" fit="cover"/><span>{{row.goods_name}}</span></div></template></el-table-column><el-table-column prop="price" label="价格" width="100"/><el-table-column prop="created_at" label="收藏时间" width="170"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button size="small" type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></el-card></div></template><script setup>import{ref,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import request from'@/utils/request';const list=ref([]);const loadList=async()=>{const res=await request({url:'/admin/user-favorites'});list.value=res.data?.list||[]};const remove=async(row)=>{await ElMessageBox.confirm('确定删除？','提示',{type:'warning'});await request({url:`/admin/user-favorites/${row.id}`,method:'delete'});ElMessage.success('删除成功');loadList()};onMounted(()=>loadList())</script>
